import {analyse, summarise, mean} from './analytics.js';
import {MAPS,recommend} from './recommender.js';
import {recommendationView} from './recommendation-view.js';
const $=s=>document.querySelector(s);
let dataset,model,data,recommenderModel,view='recommend',count=20,selectedMap='Ascent',roleFilter='All';
const fmt=(n,d=0)=>Number(n).toFixed(d);
const titles={overview:['Know your game.<br><span>Find your edge.</span>','Understand your current performance and choose what to work on.'],matches:['Every match.<br><span>A lesson waiting.</span>','Explore the matches behind your performance profile.'],insights:['Where you stand.<br><span>What to work on.</span>','ML groups your current performance with similar demo players.'],training:['Build the habits.<br><span>Raise your floor.</span>','A focused plan based on this profile’s strengths and gaps.']};
titles.recommend=['Your map.<br><span>Your next agent.</span>','Find a shortlist built around your map, experience and preferred role.'];
const matches=()=>data.matches.slice(-count).reverse();
const metrics=()=>summarise(matches());
const assessment=()=>analyse(matches(),model);
function chart(){const m=matches().reverse(),v=m.map(x=>x.damage/x.rounds),min=70,max=240;const pts=v.map((x,i)=>`${44+i*510/(v.length-1)},${155-(x-min)/(max-min)*130}`).join(' ');return `<svg class="chart" viewBox="0 0 590 185" role="img" aria-label="Damage per round across the selected ${count} fictional matches"><defs><linearGradient id="fill" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#ff4655" stop-opacity=".2"/><stop offset="1" stop-color="#ff4655" stop-opacity="0"/></linearGradient></defs>${[80,120,160,200,240].map(x=>`<line x1="42" y1="${155-(x-min)/(max-min)*130}" x2="565" y2="${155-(x-min)/(max-min)*130}" stroke="#303641" stroke-dasharray="3 5"/><text x="7" y="${159-(x-min)/(max-min)*130}">${x}</text>`).join('')}<polygon points="44,155 ${pts} 554,155" fill="url(#fill)"/><line x1="44" x2="554" y1="${155-(150-min)/(max-min)*130}" y2="${155-(150-min)/(max-min)*130}" stroke="#87909e" stroke-dasharray="5 5"/><polyline points="${pts}" stroke="#ff5969" stroke-width="2.5" fill="none" stroke-linejoin="round"/><text x="44" y="179">${count} matches ago</text><text x="513" y="179">Latest</text></svg>`}
function rows(limit=count){return matches().slice(0,limit).map(m=>`<tr><td><span class="result ${m.win?'':'loss'}">${m.win?'WIN':'LOSS'}</span></td><td class="map-cell"><b>${m.map}</b><small>${m.agent}</small></td><td>${m.score}</td><td>${m.kills} / ${m.deaths} / ${m.assists}</td><td>${fmt(m.damage/m.rounds)}</td></tr>`).join('')}
function table(limit){return `<div class="table-wrap"><table><thead><tr><th>RESULT</th><th>MAP / AGENT</th><th>SCORE</th><th>K / D / A</th><th>ADR</th></tr></thead><tbody>${rows(limit)}</tbody></table></div>`}
function agents(){return ['Jett','Raze','Reyna'].map(a=>{const m=matches().filter(x=>x.agent===a),w=m.filter(x=>x.win).length;return `<div class="agent-row"><div class="agent-letter">${a[0]}</div><div><b>${a}</b><small>${m.length} matches · ${w} wins</small><div class="bar"><i style="width:${m.length?100*w/m.length:0}%"></i></div></div><span>${m.length?fmt(100*w/m.length):'—'}%</span></div>`}).join('')}

const dimensions=['Damage contribution','Kill / death efficiency','Opening survival','Consistency'];
const tips=[['Build damage contribution','Review five low-damage rounds. Note whether you had a useful angle, took a tradeable fight, and stayed involved with your team.','15 MIN · REVIEW'],['Improve duel efficiency','Use a short deathmatch session to practise stopping before shooting and taking fights from cover. Review decisions as well as aim.','15 MIN · PRACTICE'],['Review opening deaths','Review five opening deaths. Note nearby teammates, available cover and whether someone could trade you.','15 MIN · REVIEW'],['Build repeatable routines','Compare three strong matches with three weak ones. Pick one repeatable pre-round habit and practise it in the next session.','20 MIN · REFLECTION']];
function priorities(a){return a.percentiles.map((value,i)=>({i,value})).sort((a,b)=>a.value-b.value)}
function plan(a){const p=priorities(a);return [tips[p[0].i],tips[p[1].i],['Check your progress','After practice, compare the same metrics over another match window. Keep context in mind; an individual match can be noisy.','1 SESSION · REFLECTION']]}
function loadProfile(id){
 if(!dataset)throw new Error('Demo data is still loading');
 const key=String(id??'').trim().toUpperCase(),profile=dataset.profiles.find(p=>p.id===key);
 if(!profile){$('#id-feedback').textContent='Demo ID not found. Try NOX01, SAGE02 or ROOKIE03. Your current profile is unchanged.';$('#demo-id').setAttribute('aria-invalid','true');return {ok:false,error:'Unknown demo ID'}}
 data=profile;$('#demo-id').value=profile.id;$('#demo-id').removeAttribute('aria-invalid');$('#id-feedback').textContent=`Loaded ${profile.id} · 40 fictional competitive matches.`;
 render();return {ok:true,id:data.id};
}
function render(){
 const a=assessment(),m=a.metrics,ranked=priorities(a),weak=ranked[0],strong=ranked.at(-1);
 $('#page-title').innerHTML=titles[view][0];$('#page-description').textContent=titles[view][1];
 $('#breadcrumb').textContent=({recommend:'Agent recommendations',overview:'Overview',matches:'Match history',insights:'ML insights',training:'Training plan'})[view];
 $('.identity h2').textContent=data.name+' / '+data.id;$('.identity p').textContent='APAC · Competitive · Fictional profile';$('.avatar').textContent=data.name[0].toUpperCase();$('.rank b').textContent=data.rank;$('.role b').textContent=data.role;
 document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));
 document.querySelectorAll('[data-profile]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.profile===data.id)));
 let html='';
 if(view==='recommend'){
 html=recommendationView(data,matches(),selectedMap,roleFilter,recommenderModel);
 }else if(view==='overview'){
 html=`<section class="stats">${[['Win rate',fmt(m.win)+'%','Across '+count+' demo matches'],['K/D ratio',fmt(m.kd,2),'Kills relative to deaths'],['Damage / round',fmt(m.adr),'Round-weighted average'],['Headshot rate',fmt(m.hs,1)+'%','Head hits / all recorded hits']].map(([a,b,c])=>`<article class="stat"><div class="stat-label">${a}</div><div class="stat-value">${b}</div><div class="stat-foot">${c}</div></article>`).join('')}</section><div class="grid-main"><section class="panel"><div class="section-head"><h2>Performance trend</h2><div class="legend"><span><i></i>Your ADR</span><span><i class="gray"></i>150 ADR guide</span></div></div>${chart()}<p class="chart-caption">Historical performance · the guide is illustrative, not a rank threshold.</p></section><section class="panel insight-card"><span class="badge">ML PERFORMANCE PROFILE</span><h3>${a.label}</h3><p>Closest learned pattern among ${model.trainingSamples} synthetic players. Your priority: <b>${dimensions[weak.i].toLowerCase()}</b>.</p><button class="text-button" data-go="insights">See strengths and gaps <span>↗</span></button></section></div><div class="bottom-grid"><section class="panel"><div class="section-head"><h2>Recent matches</h2><button class="text-button" data-go="matches">View all <span>↗</span></button></div>${table(4)}</section><section class="panel"><div class="section-head"><h2>Your agent pool</h2><small>WIN RATE</small></div>${agents()}<p class="panel-note">Your current results, without predicting future matches.</p></section></div>`;
 }else if(view==='matches'){
 html=`<section class="panel"><div class="section-head"><h2>Competitive match history</h2><small>${data.id} · ${count} fictional matches</small></div>${table(count)}</section>`;
 }else if(view==='insights'){
 html=`<div class="grid-main"><section class="panel"><span class="badge">K-MEANS · UNSUPERVISED ML</span><h2>Your current performance profile</h2><h3 class="profile-title">${a.label}</h3><p>The model assigns your stats to the nearest of three learned groups. Group names describe patterns; they are not skill ranks.</p><div class="wide-note">Comparison pool: ${a.referenceCount} synthetic Diamond 2 duelist profiles, using ${count}-match windows. These percentiles are not global VALORANT standings.</div><h3>Standing within the demo dataset</h3>${dimensions.map((label,i)=>`<div class="feature"><div><span>${label}</span><b>${fmt(a.percentiles[i])} / 100</b></div><div class="bar"><i style="width:${a.percentiles[i]}%"></i></div></div>`).join('')}<p class="panel-note">Percentile = share of demo players behind you on that metric. Higher is better here; opening deaths and variability are reversed. These descriptive comparisons are separate from clustering.</p></section><section class="panel"><h2>Your improvement priorities</h2><span class="badge">RELATIVE STRENGTH</span><h3>${dimensions[strong.i]}</h3><p class="muted">Your highest comparative percentile: ${fmt(strong.value)} / 100 in this synthetic pool. This is a relative strength, not proof of mastery.</p><span class="badge">FIRST FOCUS</span><h3>${tips[weak.i][0]}</h3><p>${tips[weak.i][1]}</p><button class="primary" data-go="training">Open tailored practice plan ↗</button><p class="panel-note">Advice comes from transparent rules on your two lowest percentiles. ML supplies the performance grouping; it does not prove what causes a weakness.</p></section></div><section class="panel" style="margin-top:22px"><div class="section-head"><h2>Where ML is used</h2><span class="badge">TRAINED ON SYNTHETIC DATA</span></div><p><b>Match stats → standardise features → nearest learned cluster → performance profile.</b></p><p>The model learned three cluster centres from ${model.trainingSamples} fictional players. Inputs are ADR, K/D, opening-death rate and match-to-match ADR variability. The labels were added after inspecting the learned centres.</p><p class="muted">No future-match prediction, account connection or hidden MMR estimate. Clustering has no rank-accuracy score. These simulated patterns need real-data validation before practical competitive use.</p><p class="panel-note">Esports development also includes communication, coordinated play and tournament experience. Match stats alone cannot determine professional readiness.</p></section>`;
 }else{
 const saved=getProgress(),tasks=plan(a);html=`<section class="panel"><div class="section-head"><h2>${data.id} · your next three sessions</h2><span class="badge" id="progress-label">${saved.length} / 3 COMPLETE</span></div><p>Current profile: <b>${a.label}</b>. Start with ${dimensions[weak.i].toLowerCase()}.</p><p class="muted">Saved on this device for this profile, match window and plan. Practice suggestions do not guarantee improvement.</p></section>${tasks.map(([title,desc,tag],i)=>`<label class="training-card ${saved.includes(i)?'done':''}"><input type="checkbox" data-task="${i}" ${saved.includes(i)?'checked':''}><div><h3>${title}</h3><p>${desc}</p><span class="badge">${tag}</span></div></label>`).join('')}`;
 }
 $('#content').innerHTML=html;
}
const progressKey=()=>`ascend-plan-v2-${data.id}-${count}-${priorities(assessment()).slice(0,2).map(p=>p.i).join('-')}`;
function getProgress(){try{const p=JSON.parse(localStorage.getItem(progressKey())||'[]');return Array.isArray(p)?[...new Set(p.filter(i=>[0,1,2].includes(i)))]:[]}catch{return []}}
function navigate(v){if(!Object.hasOwn(titles,v))throw new Error('Unknown view');view=v;render();return{view}}
function modal(html){$('#modal-content').innerHTML=html;$('#modal').showModal()}
$('.close').onclick=()=>$('#modal').close();
$('#connect').onclick=()=>{$('#demo-id').scrollIntoView({block:'center'});$('#demo-id').focus();$('#demo-id').select()};
$('#demo-form').onsubmit=e=>{e.preventDefault();loadProfile($('#demo-id').value)};
document.addEventListener('click',e=>{const b=e.target.closest('[data-view],[data-go],[data-profile]');if(!b||!data)return;if(b.dataset.profile)loadProfile(b.dataset.profile);else navigate(b.dataset.view||b.dataset.go)});
$('#window').onchange=e=>{count=Number(e.target.value);if(data)render()};
function setRecommendationOptions(map,role=roleFilter){if(!MAPS.includes(map)||!['All','Duelist','Controller','Initiator','Sentinel'].includes(role))throw new Error('Unsupported map or role');selectedMap=map;roleFilter=role;view='recommend';render();return {map:selectedMap,role:roleFilter,id:data.id,picks:recommend(matches(),selectedMap,data.role,recommenderModel,roleFilter).slice(0,3)}}
document.addEventListener('change',e=>{if(e.target.id==='map-select'){setRecommendationOptions(e.target.value);$('#map-select').focus()}if(e.target.id==='role-filter'){setRecommendationOptions(selectedMap,e.target.value);$('#role-filter').focus()}});
document.addEventListener('change',e=>{if(!e.target.matches('[data-task]'))return;let p=getProgress(),id=Number(e.target.dataset.task);p=e.target.checked?[...new Set([...p,id])]:p.filter(i=>i!==id);try{localStorage.setItem(progressKey(),JSON.stringify(p));render()}catch{e.target.checked=false;modal('<h2>Progress could not be saved</h2><p>Your browser is blocking device storage. The practice plan is still available.</p>')}});
$('#demo-info').onclick=()=>modal('<span class="badge">DEMO IDS, NO ACCOUNT REQUIRED</span><h2>Explore three player profiles</h2><p>Enter NOX01, SAGE02 or ROOKIE03. Each ID loads its own 40 fictional matches. These are local demo IDs, not Riot IDs.</p><p>A trained logistic regression model recommends agents by map and prior player history. A separate K-means model groups performance patterns from 600 synthetic players. Dataset percentiles and practice rules complement the model. All players use the same illustrative rank and role for this demo.</p><p>No account connection is required. Agent scores are simulated estimates, not real-world win probabilities. Practice checkboxes stay on this device.</p>');
try{
 [dataset,model,recommenderModel]=await Promise.all(['demo.json','model.json','recommender-model.json'].map(async u=>{const r=await fetch(u,{cache:'no-store'});if(!r.ok)throw new Error('Data unavailable');return r.json()}));
 $('#load-profile').disabled=false;loadProfile('NOX01');
 const context=document.modelContext;if(context?.registerTool){const lifecycle=new AbortController();window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});
 for(const tool of [{name:'configure_agent_recommendations',description:'Select a demo map and role filter, show the recommendation page and return its top candidate agents.',inputSchema:{type:'object',properties:{map:{type:'string',enum:MAPS},role:{type:'string',enum:['All','Duelist','Controller','Initiator','Sentinel']}},required:['map'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>setRecommendationOptions(input?.map,input?.role??'All')},{name:'read_performance_summary',description:'Read the selected fictional profile, statistics, learned cluster and demo-only percentiles.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({demo:true,id:data.id,matches:count,...assessment()})},{name:'navigate_performance_view',description:'Navigate to an existing Ascend view.',inputSchema:{type:'object',properties:{view:{type:'string',enum:Object.keys(titles)}},required:['view'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>navigate(input?.view)},{name:'load_demo_profile',description:'Load one fictional player by demo ID and update the dashboard.',inputSchema:{type:'object',properties:{id:{type:'string',enum:['NOX01','SAGE02','ROOKIE03']}},required:['id'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>loadProfile(input?.id)}]){try{await context.registerTool(tool,{signal:lifecycle.signal})}catch{console.warn('Optional agent tools unavailable')}}}
}catch(e){$('#content').innerHTML='<div class="error"><h2>The demo could not load</h2><p>Refresh the page to try again.</p></div>';$('#id-feedback').textContent='Demo data unavailable. Please refresh.';console.error(e)}
